import type { SupportedLocale } from "@/i18n/config";
import type { LocaleFollowup } from "@/i18n/dictionaries/locale-quality-followup";

const c = (description: string, howTo: string, formula: string, exampleNote: string, question: string, answer: string) => ({ description, howTo, formula, exampleNote, faq: { question, answer } });

export const malaysiaPhilippinesFollowups: Partial<Record<SupportedLocale, LocaleFollowup>> = {
  ko: {
    "malaysia-sst-calculator": c("말레이시아 SST 계산기는 사용자가 정한 세율로 판매세·서비스세의 금액을 산술 계산합니다. 상품 종류, 과세 서비스, 등록 의무, 면세 여부를 판정하지 않으므로 세율은 공식 분류를 확인해 직접 입력해야 합니다.", "세금 제외 금액과 적용할 세율을 입력하고 세전 금액 기준인지 세금 포함 금액 기준인지 선택하세요. 세율 선택은 사용자 책임입니다.", "세전 기준: 세액=금액×세율÷100, 합계=금액+세액. 포함 기준: 세전액=총액÷(1+세율÷100), 세액=총액−세전액입니다.", "MYR100에 사용자가 입력한 8%를 적용하면 세액 MYR8, 세금 포함 합계 MYR108입니다. 8%는 계산 예시이며 모든 상품·서비스에 적용되는 SST 세율이라는 뜻은 아닙니다.", "이 계산기가 내 거래의 SST 세율을 찾아 주나요?", "아니요. 2025년 7월 이후 판매세는 상품에 따라 10%, 5%, 특정 세율 또는 면제가 가능하고 서비스세도 서비스 종류와 시행 시기에 따라 달라집니다. 공식 분류와 거래일을 확인한 뒤 세율을 입력하세요."),
    "philippines-income-tax-calculator": c("필리핀 소득세 계산기는 연간 과세소득에 누진세율을 적용합니다. BIR 표의 개인 graduated tax rates(2023년 1월 1일부터 적용)와 구간 산술을 보여 주지만 신고서 계산기는 아닙니다.", "연간 과세소득을 PHP로 입력하세요. 총급여가 아니라 허용 공제 등을 반영한 과세소득이 기준이며, 거주 상태·공제·세액공제·선택 가능한 8% 제도는 입력되지 않습니다.", "각 구간의 소득 조각에 해당 한계세율을 적용해 합산합니다. ₱250,000까지 0%, 다음 ₱150,000은 15%, 이후 구간은 20%, 25%, 30%, ₱8,000,000 초과분은 35%입니다.", "연간 과세소득 ₱1,000,000이면 BIR graduated 표 기준 세금은 ₱152,500, 평균세율은 15.25%입니다. 계산기는 이 구간 합계를 반환하며 개인별 공제·세액공제는 반영하지 않습니다.", "이 값이 제 최종 신고 세액인가요?", "아닙니다. 거주·비거주 신분, 소득 종류, 공제, 세액공제 및 자격이 되는 납세자의 선택적 8% 방식이 반영되지 않습니다. BIR 신고와 세무 상담을 대신하지 않습니다."),
    "philippines-sss-calculator": c("SSS 계산기는 월급에 5% 직원 비율과 10% 고용주 비율을 적용해 단순 추정합니다. 실제 SSS 납부는 월급 자체가 아닌 Monthly Salary Credit 구간 및 EC·MPF 항목이 포함된 공식 표를 따릅니다.", "월 급여를 PHP로 입력하세요. 이 도구는 직원·고용주 비율의 단순 곱셈만 하며 가입 유형, 급여 구간표, EC, MPF, 적용 제외를 확인하지 않습니다.", "엔진 추정: 기준액=min(월급, ₱35,000), 직원=기준액×5%, 고용주=기준액×10%. 법정 표 금액을 계산하는 공식은 아닙니다.", "월급 ₱20,000 입력 시 엔진은 직원 ₱1,000, 고용주 ₱2,000을 표시합니다. 2025 SSS 표에는 고용주 EC가 별도 포함될 수 있고 MSC 구간을 선택하므로 이는 급여 공제액이 아닙니다.", "이 결과를 급여에서 공제해도 되나요?", "안 됩니다. SSS의 2025 표는 급여 구간별 MSC, EC 및 고액 구간 MPF를 사용합니다. 실제 납부액은 공식 표와 가입 유형으로 확인하세요."),
  },
  en: {
    "malaysia-sst-calculator": c("The Malaysia SST calculator performs arithmetic using a rate you enter for a sales- or service-tax amount. It does not classify goods or services, decide registration, exemptions, or the transaction date; choose a rate only after checking the applicable Customs category.", "Enter the amount and applicable rate, then choose whether the amount is before tax or already tax-inclusive. You are responsible for selecting the rate.", "Exclusive: tax = amount × rate ÷ 100; total = amount + tax. Inclusive: pre-tax amount = total ÷ (1 + rate ÷ 100); tax = total − pre-tax amount.", "At MYR100 with an entered 8% rate, tax is MYR8 and the total is MYR108. Eight percent is only this example's input, not a universal SST rate.", "Does this calculator find the SST rate for my transaction?", "No. From July 2025, sales-tax treatment can be 10%, 5%, a specific rate, or exempt depending on goods; service-tax rates and scope also depend on service type and effective date. Verify the official category and date before entering a rate."),
    "philippines-income-tax-calculator": c("This Philippine income-tax calculator applies graduated rates to annual taxable income. It illustrates the BIR individual graduated table effective January 1, 2023 onward; it is not a tax-return calculation.", "Enter annual taxable income in PHP. Taxable income is not necessarily gross salary; residency, income type, deductions, credits, and an eligible taxpayer's optional 8% regime are not inputs.", "Apply each marginal rate to the slice in its band and add the slices: 0% through ₱250,000, 15% on the next ₱150,000, then 20%, 25%, 30%, and 35% above ₱8,000,000.", "At ₱1,000,000 annual taxable income, the BIR graduated schedule gives ₱152,500 tax and a 15.25% average rate. The engine returns the band arithmetic without personal deductions or credits.", "Is this my final tax-return liability?", "No. Residency, income category, deductions, credits, and the optional 8% method available to eligible taxpayers are not modeled. Use the applicable BIR return guidance for filing."),
    "philippines-sss-calculator": c("The SSS calculator applies simple 5% employee and 10% employer rates to monthly pay. Actual SSS remittances use Monthly Salary Credit bands and table items such as Employees' Compensation and the Mandatory Provident Fund.", "Enter monthly pay in PHP. This tool multiplies by headline rates; it does not select a salary-credit band, membership type, EC, MPF, or an exemption.", "Engine estimate: base = min(monthly pay, ₱35,000); employee = base × 5%; employer = base × 10%. This is not the statutory table formula.", "At ₱20,000 monthly pay, the engine shows ₱1,000 employee and ₱2,000 employer. The 2025 SSS table can add employer-paid EC and uses salary-credit bands, so these are illustrative arithmetic values, not payroll remittances.", "Can I use this as the payroll deduction?", "No. The 2025 SSS schedule uses monthly salary credits by pay band, EC, and MPF at higher bands. Check the official table and membership category for an actual contribution."),
  },
  ja: {
    "malaysia-sst-calculator": c("マレーシアSST計算機は、入力した税率で売上税・サービス税の金額を算術計算します。商品・サービスの分類、登録義務、免税、取引日を判定しないため、税率は税関の該当区分を確認して選んでください。", "金額と適用税率を入力し、税抜金額か税込金額かを選択します。税率の選択は利用者が行います。", "税抜入力: 税額=金額×税率÷100、合計=金額+税額。税込入力: 税抜額=合計÷(1+税率÷100)、税額=合計−税抜額。", "MYR100に入力税率8%を使うと税額MYR8、税込合計MYR108です。8%は例の入力値で、すべての商品・サービスに適用される税率ではありません。", "取引に適用するSST税率も分かりますか？", "いいえ。2025年7月以降、売上税は品目により10%、5%、個別税率または免税となり、サービス税も種類や適用日に左右されます。公式分類と取引日を確認してください。"),
    "philippines-income-tax-calculator": c("フィリピン所得税計算機は、年間課税所得に累進税率を適用します。2023年1月1日以降のBIR個人税率表の計算例を示しますが、申告書の税額を算定するものではありません。", "年間課税所得をPHPで入力します。総給与とは限らず、居住区分、所得区分、控除、税額控除、適格者が選択できる8%方式は入力されません。", "各限界税率区分の所得部分に税率を掛けて合算します。₱250,000までは0%、次の₱150,000は15%、以降20%、25%、30%、₱8,000,000超は35%です。", "年間課税所得₱1,000,000ではBIR累進表による税額は₱152,500、平均税率は15.25%です。個人控除や税額控除は含みません。", "申告時の最終税額ですか？", "いいえ。居住区分、所得の種類、控除、税額控除、適格者向けの選択的8%方式はモデル化されていません。申告には該当するBIR案内を確認してください。"),
    "philippines-sss-calculator": c("SSS計算機は月給に従業員5%、雇用主10%を掛ける簡易計算です。実際の納付はMonthly Salary Creditの賃金帯と、EC・MPFなど公式表の項目に基づきます。", "月給をPHPで入力します。給与信用額の区分、加入種別、EC、MPF、免除を判定せず、見出し上の率を掛けるだけです。", "エンジン推定= min(月給, ₱35,000)。従業員分=基準額×5%、雇用主分=基準額×10%。法定表の計算式ではありません。", "月給₱20,000では従業員₱1,000、雇用主₱2,000を表示します。2025年のSSS表では雇用主のECが加わる場合があり、賃金信用額の帯も使うため、給与控除額ではありません。", "給与控除に使えますか？", "いいえ。2025年SSS表は賃金帯別MSC、EC、高い帯のMPFを使います。実際の納付は公式表と加入区分で確認してください。"),
  },
  zh: {
    "malaysia-sst-calculator": c("马来西亚SST计算器按用户输入的税率计算销售税或服务税金额。它不会判断商品或服务类别、登记义务、豁免或交易日期；请先核对海关适用类别再输入税率。", "输入金额和适用税率，并选择金额是未含税还是已含税。税率由用户自行确认。", "未税金额：税额=金额×税率÷100，总额=金额+税额。含税金额：未税额=总额÷(1+税率÷100)，税额=总额−未税额。", "金额MYR100、输入税率8%时，税额为MYR8，含税总额MYR108。8%只是本例输入值，并非所有商品或服务通用的SST税率。", "它能自动判断交易适用的SST税率吗？", "不能。2025年7月起，销售税可能按商品适用10%、5%、特定税率或豁免；服务税也取决于服务种类和生效日期。请按官方分类和交易日期核对。"),
    "philippines-income-tax-calculator": c("菲律宾所得税计算器对年度应税收入应用累进税率，展示BIR自2023年1月1日起的个人累进税表计算。它不是完整的报税计算器。", "以PHP输入年度应税收入。应税收入不一定等于总工资；居留身份、收入类别、扣除、抵免及符合资格者可选的8%制度均未作为输入。", "将每档边际税率乘以该档收入并求和：₱250,000以内0%，接下来₱150,000为15%，之后为20%、25%、30%，超过₱8,000,000的部分为35%。", "年度应税收入₱1,000,000按BIR累进表计算税额₱152,500，平均税率15.25%。引擎只算税阶，不含个人扣除或抵免。", "这是我的最终申报税额吗？", "不是。居留、收入类别、扣除、抵免以及符合条件者的可选8%方式均未建模。申报时请查阅适用的BIR指引。"),
    "philippines-sss-calculator": c("SSS计算器将月薪简单乘以员工5%和雇主10%。实际SSS缴费使用Monthly Salary Credit工资档，并按官方表纳入EC、MPF等项目。", "以PHP输入月薪。本工具只乘以概括费率，不选择工资信用档、会员类别，也不处理EC、MPF或豁免。", "引擎估算：基数=min(月薪, ₱35,000)；员工=基数×5%；雇主=基数×10%。这不是法定缴费表公式。", "月薪₱20,000时，引擎显示员工₱1,000、雇主₱2,000。2025年SSS表可能另计雇主EC，并按工资信用档取值，因此不能当作工资扣款额。", "可以用这个结果扣工资吗？", "不可以。2025年SSS表按工资档确定MSC，并包含EC及较高档的MPF。实际缴费请按官方表和会员类别核实。"),
  },
  es: {
    "malaysia-sst-calculator": c("La calculadora SST de Malasia hace la operación con el tipo que introduce el usuario. No clasifica bienes o servicios, registro, exenciones ni fecha de la operación; confirme la categoría oficial antes de elegir el tipo.", "Indica el importe y el tipo aplicable y señala si el importe es antes de impuestos o ya los incluye. El usuario debe seleccionar el tipo correcto.", "Sin impuesto: impuesto=importe×tipo÷100 y total=importe+impuesto. Con impuesto incluido: base=total÷(1+tipo÷100) e impuesto=total−base.", "Con MYR100 y un 8% introducido, el impuesto es MYR8 y el total MYR108. El 8% solo ilustra la operación, no es universal para SST.", "¿La herramienta identifica el tipo SST de mi operación?", "No. Desde julio de 2025, el impuesto sobre ventas puede ser 10%, 5%, específico o exento según el bien; el impuesto sobre servicios depende del servicio y la fecha. Comprueba la clasificación oficial."),
    "philippines-income-tax-calculator": c("Esta calculadora filipina aplica tipos progresivos a la renta imponible anual según la tabla individual de BIR vigente desde el 1 de enero de 2023. No calcula una declaración completa.", "Introduce la renta imponible anual en PHP. No siempre equivale al salario bruto; no se solicitan residencia fiscal, tipo de renta, deducciones, créditos ni el régimen opcional del 8% para quienes reúnen los requisitos.", "Aplica cada tipo marginal a la parte de renta de su tramo y suma: 0% hasta ₱250.000, 15% sobre los siguientes ₱150.000, después 20%, 25%, 30% y 35% sobre el exceso de ₱8.000.000.", "Con ₱1.000.000 de renta imponible, la tabla progresiva de BIR da ₱152.500 y una tasa media de 15,25%. El motor no aplica deducciones o créditos personales.", "¿Es el impuesto final de mi declaración?", "No. Residencia, categoría de ingresos, deducciones, créditos y el régimen opcional del 8% para contribuyentes elegibles no se modelan. Consulte la guía BIR aplicable para declarar."),
    "philippines-sss-calculator": c("La calculadora SSS multiplica el salario mensual por tasas simples del 5% para el empleado y 10% para el empleador. Las aportaciones reales usan tramos de Monthly Salary Credit y partidas oficiales como EC y MPF.", "Introduce el salario mensual en PHP. La herramienta no selecciona un tramo de crédito salarial ni el tipo de afiliación y no incluye EC, MPF o exenciones.", "Estimación del motor: base=min(salario mensual, ₱35.000); empleado=base×5%; empleador=base×10%. No es la fórmula de la tabla legal.", "Con ₱20.000 al mes, el motor muestra ₱1.000 del empleado y ₱2.000 del empleador. La tabla SSS 2025 puede añadir EC del empleador y usa tramos MSC; no es una retención de nómina.", "¿Puedo usarlo como deducción de nómina?", "No. El calendario SSS 2025 usa créditos salariales por tramo, EC y MPF para las bandas superiores. Compruebe la tabla oficial y la categoría de afiliación."),
  },
  "pt-br": {
    "malaysia-sst-calculator": c("A calculadora SST da Malásia faz a conta com a alíquota informada pelo usuário. Ela não classifica mercadorias ou serviços, registro, isenções nem data da operação; confirme a categoria oficial antes de escolher a alíquota.", "Informe o valor e a alíquota aplicável e selecione se o valor é antes do imposto ou já inclui o imposto. A escolha da alíquota cabe ao usuário.", "Sem imposto: imposto=valor×alíquota÷100 e total=valor+imposto. Com imposto incluído: base=total÷(1+alíquota÷100) e imposto=total−base.", "Com MYR100 e alíquota informada de 8%, o imposto é MYR8 e o total MYR108. 8% é apenas um exemplo, não uma alíquota SST universal.", "A ferramenta identifica a alíquota SST da minha operação?", "Não. Desde julho de 2025, o imposto sobre vendas pode ser 10%, 5%, específico ou isento conforme o produto; o imposto sobre serviços depende do serviço e da vigência. Confira a classificação oficial."),
    "philippines-income-tax-calculator": c("Esta calculadora filipina aplica faixas progressivas à renda tributável anual conforme a tabela individual do BIR vigente desde 1º de janeiro de 2023. Não calcula uma declaração completa.", "Informe a renda tributável anual em PHP. Ela pode diferir do salário bruto; residência fiscal, tipo de renda, deduções, créditos e o regime opcional de 8% para elegíveis não são campos do cálculo.", "Aplique cada alíquota marginal à parcela da faixa correspondente e some: 0% até ₱250.000, 15% nos próximos ₱150.000, depois 20%, 25%, 30% e 35% sobre o excedente de ₱8.000.000.", "Com renda tributável de ₱1.000.000, a tabela progressiva do BIR resulta em ₱152.500 e alíquota média de 15,25%. O motor não inclui deduções ou créditos pessoais.", "Este é o imposto final da minha declaração?", "Não. Residência, categoria de renda, deduções, créditos e o regime opcional de 8% para contribuintes elegíveis não são modelados. Consulte a orientação BIR aplicável à declaração."),
    "philippines-sss-calculator": c("A calculadora SSS aplica taxas simples de 5% para o empregado e 10% para o empregador sobre o salário mensal. As contribuições reais usam faixas de Monthly Salary Credit e itens da tabela oficial, como EC e MPF.", "Informe o salário mensal em PHP. A ferramenta não seleciona a faixa de crédito salarial nem o tipo de filiação e não inclui EC, MPF ou isenções.", "Estimativa do motor: base=min(salário mensal, ₱35.000); empregado=base×5%; empregador=base×10%. Não é a fórmula da tabela legal.", "Com ₱20.000 mensais, o motor mostra ₱1.000 do empregado e ₱2.000 do empregador. A tabela SSS 2025 pode incluir EC do empregador e usa faixas MSC; não é valor de folha.", "Posso usar como desconto em folha?", "Não. A tabela SSS 2025 usa créditos salariais por faixa, EC e MPF nas faixas superiores. Confira a tabela oficial e a categoria de filiação."),
  },
  de: {
    "malaysia-sst-calculator": c("Der malaysische SST-Rechner rechnet mit einem vom Nutzer eingegebenen Steuersatz. Er ordnet keine Waren oder Dienstleistungen ein und prüft weder Registrierung, Befreiung noch Transaktionsdatum; den Satz müssen Sie anhand der amtlichen Kategorie bestimmen.", "Betrag und anwendbaren Satz eingeben und wählen, ob der Betrag netto oder bereits inklusive Steuer ist. Die Auswahl des Satzes liegt bei Ihnen.", "Netto: Steuer=Betrag×Satz÷100; Gesamt=Betrag+Steuer. Inklusive: Nettobetrag=Gesamt÷(1+Satz÷100); Steuer=Gesamt−Nettobetrag.", "Bei MYR100 und eingegebenen 8% beträgt die Steuer MYR8, die Summe MYR108. Die 8% dienen nur als Rechenbeispiel und sind kein allgemeiner SST-Satz.", "Ermittelt der Rechner den SST-Satz für meinen Umsatz?", "Nein. Seit Juli 2025 können Waren je nach Kategorie mit 10%, 5%, einem spezifischen Satz oder steuerfrei behandelt werden; Dienstleistungen hängen ebenfalls von Art und Stichtag ab. Prüfen Sie die amtliche Einordnung."),
    "philippines-income-tax-calculator": c("Dieser philippinische Einkommensteuerrechner wendet progressive Sätze auf das jährliche steuerpflichtige Einkommen an. Er zeigt die individuelle BIR-Tabelle ab 1. Januar 2023, ist aber keine vollständige Steuererklärung.", "Jährliches steuerpflichtiges Einkommen in PHP eingeben. Es ist nicht zwingend das Bruttogehalt; Ansässigkeit, Einkunftsart, Abzüge, Gutschriften und das optionale 8%-Verfahren für Berechtigte fehlen.", "Jeden Einkommensanteil mit seinem Grenzsteuersatz multiplizieren und addieren: 0% bis ₱250.000, 15% auf die nächsten ₱150.000, danach 20%, 25%, 30% und 35% über ₱8.000.000.", "Bei ₱1.000.000 steuerpflichtigem Einkommen ergibt die BIR-Tabelle ₱152.500 Steuer und 15,25% Durchschnittssatz. Persönliche Abzüge und Gutschriften sind nicht enthalten.", "Ist das meine endgültige Steuer für die Erklärung?", "Nein. Ansässigkeit, Einkunftsart, Abzüge, Gutschriften und das optionale 8%-Verfahren für Berechtigte sind nicht modelliert. Nutzen Sie für die Erklärung die zutreffenden BIR-Hinweise."),
    "philippines-sss-calculator": c("Der SSS-Rechner multipliziert den Monatslohn mit einfachen 5% Arbeitnehmer- und 10% Arbeitgeberanteilen. Tatsächliche Beiträge folgen Monthly-Salary-Credit-Stufen und offiziellen Tabellenposten wie EC und MPF.", "Monatslohn in PHP eingeben. Der Rechner wählt weder MSC-Stufe noch Mitgliedskategorie und berücksichtigt EC, MPF oder Ausnahmen nicht.", "Motorschätzung: Basis=min(Monatslohn, ₱35.000); Arbeitnehmer=Basis×5%; Arbeitgeber=Basis×10%. Das ist nicht die gesetzliche Tabellenberechnung.", "Bei ₱20.000 Monatslohn zeigt die Engine ₱1.000 Arbeitnehmer- und ₱2.000 Arbeitgeberanteil. Die SSS-Tabelle 2025 kann Arbeitgeber-EC ergänzen und verwendet MSC-Stufen; dies ist kein Lohnabzug.", "Kann ich das als Lohnabzug verwenden?", "Nein. Die SSS-Tabelle 2025 staffelt MSC, enthält EC und bei höheren Stufen MPF. Für echte Beiträge sind die offizielle Tabelle und Mitgliedskategorie maßgeblich."),
  },
  fr: {
    "malaysia-sst-calculator": c("Le calculateur SST de Malaisie effectue le calcul avec le taux saisi par l’utilisateur. Il ne classe pas les biens ou services et ne détermine ni inscription, exonération ni date d’opération; vérifiez la catégorie officielle avant de choisir le taux.", "Saisissez le montant et le taux applicable, puis indiquez si le montant est hors taxe ou déjà TTC. Le choix du taux vous revient.", "Hors taxe: taxe=montant×taux÷100; total=montant+taxe. TTC: base=total÷(1+taux÷100); taxe=total−base.", "Pour MYR100 avec un taux saisi de 8%, la taxe est MYR8 et le total MYR108. 8% est une valeur d’exemple, pas un taux SST universel.", "Le calculateur trouve-t-il le taux SST de mon opération?", "Non. Depuis juillet 2025, les biens peuvent relever de 10%, 5%, d’un taux spécifique ou d’une exonération; les services dépendent aussi de leur catégorie et de la date. Vérifiez le classement officiel."),
    "philippines-income-tax-calculator": c("Ce calculateur philippin applique des tranches progressives au revenu annuel imposable selon le barème individuel du BIR en vigueur depuis le 1er janvier 2023. Ce n’est pas une déclaration complète.", "Saisissez le revenu annuel imposable en PHP. Il peut différer du salaire brut; résidence, nature des revenus, déductions, crédits et régime optionnel de 8% pour les personnes admissibles ne sont pas demandés.", "Appliquez chaque taux marginal à la part de revenu de la tranche puis additionnez: 0% jusqu’à ₱250.000, 15% sur les ₱150.000 suivants, puis 20%, 25%, 30% et 35% au-delà de ₱8.000.000.", "Pour ₱1.000.000 de revenu imposable, le barème progressif du BIR donne ₱152.500 d’impôt et un taux moyen de 15,25%. Les déductions et crédits personnels sont exclus.", "Est-ce le montant final de ma déclaration?", "Non. Résidence, catégorie de revenus, déductions, crédits et régime optionnel de 8% des contribuables admissibles ne sont pas modélisés. Consultez les consignes BIR applicables."),
    "philippines-sss-calculator": c("Le calculateur SSS applique des taux simples de 5% pour le salarié et de 10% pour l’employeur au salaire mensuel. Les cotisations réelles utilisent des tranches de Monthly Salary Credit et des éléments officiels tels que EC et MPF.", "Saisissez le salaire mensuel en PHP. L’outil ne choisit pas la tranche MSC ou le type d’adhésion et n’inclut ni EC, ni MPF, ni exemptions.", "Estimation du moteur: base=min(salaire mensuel, ₱35.000); salarié=base×5%; employeur=base×10%. Ce n’est pas le calcul du barème légal.", "À ₱20.000 par mois, le moteur affiche ₱1.000 salarié et ₱2.000 employeur. Le barème SSS 2025 peut ajouter l’EC patronal et utilise des tranches MSC; ce n’est pas un montant de paie.", "Puis-je utiliser ce résultat comme retenue de paie?", "Non. Le barème SSS 2025 utilise des crédits salariaux par tranche, l’EC et le MPF aux tranches supérieures. Vérifiez le barème officiel et la catégorie d’adhésion."),
  },
  vi: {
    "malaysia-sst-calculator": c("Máy tính SST Malaysia thực hiện phép tính theo mức thuế người dùng nhập. Công cụ không phân loại hàng hóa/dịch vụ, nghĩa vụ đăng ký, miễn thuế hay ngày giao dịch; hãy xác minh nhóm chính thức trước khi chọn mức thuế.", "Nhập số tiền và mức thuế áp dụng, rồi chọn số tiền chưa thuế hay đã gồm thuế. Người dùng tự chịu trách nhiệm chọn mức.", "Chưa gồm thuế: thuế=số tiền×mức÷100; tổng=số tiền+thuế. Đã gồm thuế: trước thuế=tổng÷(1+mức÷100); thuế=tổng−trước thuế.", "Với MYR100 và mức nhập 8%, thuế là MYR8, tổng MYR108. 8% chỉ là đầu vào ví dụ, không phải mức SST chung cho mọi hàng hóa/dịch vụ.", "Công cụ có tìm đúng mức SST cho giao dịch không?", "Không. Từ tháng 7/2025, hàng hóa có thể chịu 10%, 5%, mức cụ thể hoặc được miễn tùy phân loại; dịch vụ cũng phụ thuộc loại dịch vụ và ngày hiệu lực. Hãy đối chiếu phân loại chính thức."),
    "philippines-income-tax-calculator": c("Máy tính thuế thu nhập Philippines áp dụng các bậc lũy tiến lên thu nhập chịu thuế năm theo bảng cá nhân của BIR có hiệu lực từ 1/1/2023. Đây không phải công cụ lập tờ khai đầy đủ.", "Nhập thu nhập chịu thuế năm bằng PHP. Con số này có thể khác lương gộp; tình trạng cư trú, loại thu nhập, khoản giảm trừ, tín dụng và lựa chọn thuế 8% của người đủ điều kiện không được nhập.", "Tính thuế từng phần theo thuế suất biên rồi cộng: 0% đến ₱250.000, 15% cho ₱150.000 tiếp theo, sau đó 20%, 25%, 30% và 35% phần vượt ₱8.000.000.", "Với thu nhập chịu thuế ₱1.000.000, bảng lũy tiến BIR cho thuế ₱152.500 và tỷ lệ bình quân 15,25%. Công cụ không tính giảm trừ hay tín dụng cá nhân.", "Đây có phải số thuế cuối cùng trên tờ khai của tôi?", "Không. Cư trú, loại thu nhập, giảm trừ, tín dụng và chế độ 8% tùy chọn cho người đủ điều kiện không được mô hình hóa. Hãy tham khảo hướng dẫn BIR phù hợp."),
    "philippines-sss-calculator": c("Máy tính SSS nhân lương tháng với tỷ lệ đơn giản 5% của người lao động và 10% của chủ sử dụng. Khoản đóng thực tế dựa trên bậc Monthly Salary Credit và các mục trong bảng chính thức như EC và MPF.", "Nhập lương tháng bằng PHP. Công cụ không chọn bậc tín dụng lương hay loại thành viên và không tính EC, MPF hoặc miễn trừ.", "Ước tính của engine: cơ sở=min(lương tháng, ₱35.000); người lao động=cơ sở×5%; chủ sử dụng=cơ sở×10%. Đây không phải công thức bảng luật định.", "Với ₱20.000 mỗi tháng, engine cho ₱1.000 phía người lao động và ₱2.000 phía chủ sử dụng. Bảng SSS 2025 có thể cộng EC do chủ trả và dùng bậc MSC; đây không phải số khấu trừ lương.", "Có thể dùng số này để khấu trừ lương không?", "Không. Lịch SSS 2025 dùng MSC theo bậc, EC và MPF ở bậc cao. Hãy kiểm tra bảng chính thức và loại thành viên để xác định khoản đóng."),
  },
  id: {
    "malaysia-sst-calculator": c("Kalkulator SST Malaysia menghitung berdasarkan tarif yang dimasukkan pengguna. Alat ini tidak menentukan klasifikasi barang/jasa, kewajiban pendaftaran, pengecualian, atau tanggal transaksi; periksa kategori resmi sebelum memilih tarif.", "Masukkan nilai dan tarif yang berlaku, lalu pilih apakah nilai sebelum pajak atau sudah termasuk pajak. Pengguna bertanggung jawab memilih tarif.", "Sebelum pajak: pajak=nilai×tarif÷100; total=nilai+pajak. Termasuk pajak: nilai dasar=total÷(1+tarif÷100); pajak=total−nilai dasar.", "Untuk MYR100 dengan tarif masukan 8%, pajaknya MYR8 dan total MYR108. Angka 8% hanya contoh perhitungan, bukan tarif SST universal.", "Apakah kalkulator menentukan tarif SST transaksi saya?", "Tidak. Sejak Juli 2025, pajak penjualan barang dapat 10%, 5%, tarif khusus, atau dikecualikan; pajak layanan juga bergantung pada jenis layanan dan tanggal berlaku. Verifikasi kategori resmi."),
    "philippines-income-tax-calculator": c("Kalkulator pajak penghasilan Filipina menerapkan tarif progresif pada penghasilan kena pajak tahunan menurut tabel individu BIR yang berlaku sejak 1 Januari 2023. Ini bukan kalkulator pelaporan pajak lengkap.", "Masukkan penghasilan kena pajak tahunan dalam PHP. Nilainya tidak selalu sama dengan gaji bruto; domisili pajak, jenis penghasilan, pengurang, kredit, dan rezim opsional 8% untuk wajib pajak yang memenuhi syarat tidak diminta.", "Kalikan tiap bagian penghasilan dalam lapisan marginal dengan tarifnya, lalu jumlahkan: 0% sampai ₱250.000, 15% untuk ₱150.000 berikutnya, kemudian 20%, 25%, 30%, dan 35% di atas ₱8.000.000.", "Penghasilan kena pajak ₱1.000.000 menghasilkan pajak ₱152.500 dan tarif rata-rata 15,25% menurut tabel progresif BIR. Pengurang dan kredit pribadi tidak diterapkan.", "Apakah ini pajak akhir pada SPT saya?", "Tidak. Domisili, kategori penghasilan, pengurang, kredit, serta pilihan tarif 8% bagi yang memenuhi syarat tidak dimodelkan. Gunakan panduan BIR yang sesuai untuk pelaporan."),
    "philippines-sss-calculator": c("Kalkulator SSS mengalikan gaji bulanan dengan tarif sederhana 5% pekerja dan 10% pemberi kerja. Iuran sebenarnya memakai tingkat Monthly Salary Credit dan komponen tabel resmi seperti EC dan MPF.", "Masukkan gaji bulanan dalam PHP. Alat tidak memilih tingkat kredit gaji atau kategori keanggotaan dan tidak memasukkan EC, MPF, atau pengecualian.", "Estimasi mesin: dasar=min(gaji bulanan, ₱35.000); pekerja=dasar×5%; pemberi kerja=dasar×10%. Ini bukan rumus tabel undang-undang.", "Pada gaji ₱20.000, mesin menunjukkan pekerja ₱1.000 dan pemberi kerja ₱2.000. Tabel SSS 2025 dapat menambahkan EC pemberi kerja dan memakai tingkat MSC; hasil ini bukan potongan penggajian.", "Bisakah angka ini dipakai sebagai potongan gaji?", "Tidak. Jadwal SSS 2025 memakai MSC menurut rentang, EC, dan MPF pada rentang tinggi. Periksa tabel resmi dan kategori anggota."),
  },
  th: {
    "malaysia-sst-calculator": c("เครื่องคำนวณ SST ของมาเลเซียคำนวณตามอัตราที่ผู้ใช้ป้อน แต่ไม่จัดประเภทสินค้า/บริการ ตรวจหน้าที่จดทะเบียน การยกเว้น หรือวันที่ทำรายการ โปรดตรวจหมวดอย่างเป็นทางการก่อนเลือกอัตรา", "ป้อนยอดและอัตราที่ใช้ แล้วเลือกว่ายอดก่อนภาษีหรือรวมภาษีแล้ว ผู้ใช้ต้องเลือกอัตราเอง", "ก่อนภาษี: ภาษี=ยอด×อัตรา÷100; รวม=ยอด+ภาษี รวมภาษีแล้ว: ฐานก่อนภาษี=ยอดรวม÷(1+อัตรา÷100); ภาษี=ยอดรวม−ฐาน", "MYR100 ที่อัตราป้อน 8% ได้ภาษี MYR8 รวม MYR108 อัตรา 8% เป็นเพียงตัวอย่างคำนวณ ไม่ใช่อัตรา SST ที่ใช้กับทุกกรณี", "เครื่องมือนี้หาอัตรา SST ของรายการให้หรือไม่?", "ไม่ ตั้งแต่กรกฎาคม 2025 ภาษีขายอาจเป็น 10%, 5%, อัตราเฉพาะ หรือได้รับยกเว้นตามสินค้า ส่วนภาษีบริการขึ้นกับประเภทบริการและวันมีผล โปรดตรวจหมวดทางการ"),
    "philippines-income-tax-calculator": c("เครื่องคำนวณภาษีเงินได้ฟิลิปปินส์ใช้อัตราก้าวหน้ากับเงินได้พึงประเมินรายปีตามตารางบุคคลของ BIR ที่มีผลตั้งแต่ 1 มกราคม 2023 ไม่ใช่เครื่องคำนวณแบบยื่นแบบครบถ้วน", "ป้อนเงินได้พึงประเมินรายปีเป็น PHP ซึ่งอาจไม่เท่ากับเงินเดือนรวม ระบบไม่ถามถิ่นที่อยู่ ประเภทเงินได้ ค่าลดหย่อน เครดิตภาษี หรือทางเลือกอัตรา 8% สำหรับผู้มีสิทธิ", "คูณเงินได้แต่ละส่วนด้วยอัตราขั้น marginal แล้วรวม: 0% ถึง ₱250,000, 15% สำหรับ ₱150,000 ถัดไป จากนั้น 20%, 25%, 30% และ 35% สำหรับส่วนเกิน ₱8,000,000", "เงินได้พึงประเมิน ₱1,000,000 ตามตาราง BIR คำนวณภาษี ₱152,500 และอัตราเฉลี่ย 15.25% ระบบไม่หักค่าลดหย่อนหรือเครดิตส่วนบุคคล", "นี่คือภาษีสุดท้ายในแบบยื่นของฉันหรือไม่?", "ไม่ ระบบไม่คำนวณถิ่นที่อยู่ ประเภทเงินได้ ค่าลดหย่อน เครดิต หรือทางเลือก 8% สำหรับผู้มีสิทธิ โปรดใช้แนวทาง BIR ที่ตรงกับการยื่นจริง"),
    "philippines-sss-calculator": c("เครื่องคำนวณ SSS คูณเงินเดือนรายเดือนด้วยอัตราอย่างง่าย 5% ของลูกจ้างและ 10% ของนายจ้าง เงินสมทบจริงใช้ช่วง Monthly Salary Credit และรายการในตารางทางการ เช่น EC และ MPF", "ป้อนเงินเดือนรายเดือนเป็น PHP เครื่องมือไม่เลือกช่วงเครดิตเงินเดือนหรือประเภทสมาชิก และไม่รวม EC, MPF หรือข้อยกเว้น", "ค่าประมาณของ engine: ฐาน=min(เงินเดือน, ₱35,000); ลูกจ้าง=ฐาน×5%; นายจ้าง=ฐาน×10% ไม่ใช่สูตรตารางตามกฎหมาย", "เงินเดือน ₱20,000 ได้ผลลูกจ้าง ₱1,000 และนายจ้าง ₱2,000 ตาราง SSS ปี 2025 อาจเพิ่ม EC ฝั่งนายจ้างและใช้ช่วง MSC ผลนี้จึงไม่ใช่ยอดหักเงินเดือนจริง", "ใช้ตัวเลขนี้หักเงินเดือนได้หรือไม่?", "ไม่ได้ ตาราง SSS ปี 2025 ใช้ MSC ตามช่วง รวม EC และ MPF ในช่วงสูง โปรดตรวจตารางทางการและประเภทสมาชิก"),
  },
  "zh-tw": {
    "malaysia-sst-calculator": c("馬來西亞SST計算器依使用者輸入的稅率進行銷售稅或服務稅算術計算，不會判斷商品／服務分類、登記義務、免稅或交易日期。請先查官方分類再輸入稅率。", "輸入金額和適用稅率，再選擇金額未稅或已含稅。稅率由使用者自行確認。", "未稅：稅額=金額×稅率÷100，合計=金額+稅額。含稅：未稅金額=總額÷(1+稅率÷100)，稅額=總額−未稅金額。", "MYR100輸入8%時，稅額MYR8，含稅總額MYR108。8%僅為本例輸入值，不代表所有商品或服務都適用此SST稅率。", "計算器會自動找出交易適用的SST稅率嗎？", "不會。2025年7月起，銷售稅可能依商品適用10%、5%、特定稅率或免稅；服務稅也依服務種類及生效日而異。請核對官方分類與交易日期。"),
    "philippines-income-tax-calculator": c("菲律賓所得稅計算器依年度課稅所得套用累進稅率，示範BIR自2023年1月1日起適用的個人稅率表；它不是完整報稅工具。", "以PHP輸入年度課稅所得。課稅所得不一定等於總薪資；居留身分、所得種類、扣除額、抵減額及符合資格者的8%選擇制都不是輸入項目。", "將各邊際級距的所得部分乘以稅率後加總：₱250,000以內0%，接下來₱150,000為15%，其後20%、25%、30%，超過₱8,000,000部分為35%。", "年度課稅所得₱1,000,000依BIR累進表得稅額₱152,500，平均稅率15.25%。引擎不計個人扣除或抵減。", "這是我報稅的最終稅額嗎？", "不是。居留身分、所得類別、扣除額、抵減額，以及符合資格者可選的8%方式均未建模。申報時請查閱適用的BIR指引。"),
    "philippines-sss-calculator": c("SSS計算器以月薪簡單乘上員工5%與雇主10%。實際SSS繳款使用Monthly Salary Credit薪資級距，並依官方表納入EC、MPF等項目。", "以PHP輸入月薪。本工具不選擇MSC級距或會員類別，也不計EC、MPF或豁免。", "引擎估算：基數=min(月薪, ₱35,000)；員工=基數×5%；雇主=基數×10%。這不是法定繳費表公式。", "月薪₱20,000時，引擎顯示員工₱1,000、雇主₱2,000。2025年SSS表可能另計雇主EC，且依MSC級距計算，因此不能視為實際薪資扣款。", "可以用這個結果扣薪嗎？", "不可以。2025年SSS表按薪資級距決定MSC，並含EC及高級距MPF。實際繳款請依官方表及會員類別確認。"),
  },
  it: {
    "malaysia-sst-calculator": c("Il calcolatore SST malese esegue il calcolo con l’aliquota inserita dall’utente. Non classifica beni o servizi e non determina registrazione, esenzioni o data dell’operazione; verifica la categoria ufficiale prima di scegliere l’aliquota.", "Inserisci importo e aliquota applicabile, poi indica se l’importo è al netto o include già l’imposta. La scelta dell’aliquota spetta all’utente.", "Esclusa: imposta=importo×aliquota÷100; totale=importo+imposta. Inclusa: imponibile=totale÷(1+aliquota÷100); imposta=totale−imponibile.", "Con MYR100 e aliquota inserita dell’8%, l’imposta è MYR8 e il totale MYR108. L’8% è solo un esempio, non un’aliquota SST universale.", "Il calcolatore individua l’aliquota SST della mia operazione?", "No. Da luglio 2025, per i beni l’imposta sulle vendite può essere 10%, 5%, specifica o esente; i servizi dipendono dal tipo e dalla data. Verifica la classificazione ufficiale."),
    "philippines-income-tax-calculator": c("Questo calcolatore filippino applica aliquote progressive al reddito imponibile annuale secondo la tabella individuale BIR in vigore dal 1º gennaio 2023. Non calcola una dichiarazione completa.", "Inserisci il reddito imponibile annuale in PHP. Può differire dallo stipendio lordo; residenza, tipo di reddito, deduzioni, crediti e regime opzionale dell’8% per chi ne ha diritto non sono input.", "Applica ogni aliquota marginale alla parte di reddito della fascia e somma: 0% fino a ₱250.000, 15% sui successivi ₱150.000, poi 20%, 25%, 30% e 35% oltre ₱8.000.000.", "Con ₱1.000.000 imponibili, la tabella progressiva BIR dà ₱152.500 d’imposta e un’aliquota media del 15,25%. Non include deduzioni o crediti personali.", "È l’imposta finale della mia dichiarazione?", "No. Residenza, categoria di reddito, deduzioni, crediti e regime opzionale dell’8% per gli aventi diritto non sono modellati. Consulta le istruzioni BIR applicabili."),
    "philippines-sss-calculator": c("Il calcolatore SSS moltiplica lo stipendio mensile per aliquote semplici del 5% per il lavoratore e del 10% per il datore. I contributi effettivi usano fasce di Monthly Salary Credit e voci ufficiali come EC e MPF.", "Inserisci lo stipendio mensile in PHP. Lo strumento non seleziona la fascia MSC o il tipo di adesione e non include EC, MPF o esenzioni.", "Stima del motore: base=min(stipendio mensile, ₱35.000); lavoratore=base×5%; datore=base×10%. Non è il calcolo della tabella legale.", "Con ₱20.000 mensili, il motore mostra ₱1.000 lavoratore e ₱2.000 datore. La tabella SSS 2025 può aggiungere EC a carico del datore e usa fasce MSC: non è una trattenuta in busta paga.", "Posso usare il risultato come trattenuta?", "No. La tabella SSS 2025 usa crediti salariali per fascia, EC e MPF nelle fasce alte. Verifica la tabella ufficiale e la categoria di adesione."),
  },
  nl: {
    "malaysia-sst-calculator": c("De Maleisische SST-calculator rekent met een door de gebruiker ingevoerd tarief. De tool classificeert geen goederen of diensten en bepaalt geen registratie, vrijstelling of transactiedatum; controleer eerst de officiële categorie.", "Voer bedrag en toepasselijk tarief in en kies of het bedrag exclusief of inclusief belasting is. U kiest zelf het juiste tarief.", "Exclusief: belasting=bedrag×tarief÷100; totaal=bedrag+belasting. Inclusief: grondslag=totaal÷(1+tarief÷100); belasting=totaal−grondslag.", "Bij MYR100 en een ingevoerd tarief van 8% is de belasting MYR8 en het totaal MYR108. 8% is alleen een rekenvoorbeeld, geen universeel SST-tarief.", "Bepaalt de calculator het SST-tarief voor mijn transactie?", "Nee. Sinds juli 2025 kan verkoopbelasting voor goederen 10%, 5%, een specifiek tarief of vrijgesteld zijn; servicetax hangt ook af van diensttype en ingangsdatum. Controleer de officiële indeling."),
    "philippines-income-tax-calculator": c("Deze Filipijnse inkomstenbelastingcalculator past progressieve schijven toe op jaarlijks belastbaar inkomen volgens de individuele BIR-tabel vanaf 1 januari 2023. Het is geen volledige aangifteberekening.", "Voer jaarlijks belastbaar inkomen in PHP in. Dat is niet altijd het brutoloon; woonplaats, inkomenssoort, aftrekposten, credits en de optionele 8%-regeling voor wie daarvoor in aanmerking komt ontbreken.", "Vermenigvuldig elk inkomensdeel met het marginale tarief en tel op: 0% tot ₱250.000, 15% over de volgende ₱150.000, daarna 20%, 25%, 30% en 35% boven ₱8.000.000.", "Bij ₱1.000.000 belastbaar inkomen geeft de BIR-tabel ₱152.500 belasting en een gemiddeld tarief van 15,25%. Persoonlijke aftrekposten en credits zijn niet verwerkt.", "Is dit mijn definitieve belastingaanslag?", "Nee. Woonplaats, inkomenscategorie, aftrekposten, credits en de optionele 8%-methode voor gerechtigden zijn niet gemodelleerd. Raadpleeg de toepasselijke BIR-aangifteregels."),
    "philippines-sss-calculator": c("De SSS-calculator vermenigvuldigt maandloon met eenvoudige tarieven van 5% voor de werknemer en 10% voor de werkgever. Werkelijke bijdragen volgen Monthly Salary Credit-schijven en officiële posten zoals EC en MPF.", "Voer maandloon in PHP in. De tool kiest geen MSC-schijf of lidmaatschapstype en neemt EC, MPF of vrijstellingen niet mee.", "Motorschatting: basis=min(maandloon, ₱35.000); werknemer=basis×5%; werkgever=basis×10%. Dit is niet de wettelijke tabelberekening.", "Bij ₱20.000 per maand toont de engine ₱1.000 werknemer en ₱2.000 werkgever. De SSS-tabel 2025 kan werkgevers-EC toevoegen en gebruikt MSC-schijven; dit is geen looninhouding.", "Kan ik dit als looninhouding gebruiken?", "Nee. De SSS-regeling van 2025 gebruikt MSC per loonklasse, EC en MPF bij hogere klassen. Controleer de officiële tabel en lidmaatschapscategorie."),
  },
  hi: {
    "malaysia-sst-calculator": c("मलेशिया SST कैलकुलेटर उपयोगकर्ता द्वारा दर्ज दर से बिक्री या सेवा कर की गणना करता है। यह वस्तुओं/सेवाओं का वर्गीकरण, पंजीकरण, छूट या लेन-देन की तारीख तय नहीं करता; दर चुनने से पहले आधिकारिक श्रेणी जाँचें।", "राशि और लागू दर दर्ज करें, फिर चुनें कि राशि कर से पहले है या कर सहित। सही दर चुनना उपयोगकर्ता की जिम्मेदारी है।", "कर-पूर्व: कर=राशि×दर÷100, कुल=राशि+कर। कर-सहित: आधार=कुल÷(1+दर÷100), कर=कुल−आधार।", "MYR100 पर दर्ज 8% से कर MYR8 और कुल MYR108 होता है। 8% केवल उदाहरण का इनपुट है, सार्वभौमिक SST दर नहीं।", "क्या यह मेरे लेन-देन की SST दर खोजता है?", "नहीं। जुलाई 2025 से वस्तुओं पर बिक्री कर 10%, 5%, विशिष्ट दर या छूट हो सकती है; सेवा कर सेवा-प्रकार और लागू तारीख पर निर्भर है। आधिकारिक वर्गीकरण देखें।"),
    "philippines-income-tax-calculator": c("यह फिलीपीनी आयकर कैलकुलेटर वार्षिक करयोग्य आय पर 1 जनवरी 2023 से प्रभावी BIR की व्यक्तिगत प्रगतिशील दरें लागू करता है। यह पूर्ण रिटर्न कैलकुलेशन नहीं है।", "वार्षिक करयोग्य आय PHP में दर्ज करें। यह सकल वेतन से अलग हो सकती है; निवास स्थिति, आय प्रकार, कटौतियाँ, क्रेडिट और पात्र लोगों की वैकल्पिक 8% व्यवस्था इनपुट नहीं हैं।", "हर सीमांत स्लैब में आय के हिस्से पर दर लगाकर जोड़ें: ₱250,000 तक 0%, अगले ₱150,000 पर 15%, फिर 20%, 25%, 30%, और ₱8,000,000 से ऊपर 35%।", "₱1,000,000 करयोग्य आय पर BIR तालिका के अनुसार कर ₱152,500 और औसत दर 15.25% है। व्यक्तिगत कटौतियाँ या क्रेडिट लागू नहीं होते।", "क्या यह मेरा अंतिम रिटर्न टैक्स है?", "नहीं। निवास, आय-वर्ग, कटौती, क्रेडिट और पात्र करदाता की वैकल्पिक 8% व्यवस्था मॉडल नहीं की गई है। दाखिल करने के लिए लागू BIR निर्देश देखें।"),
    "philippines-sss-calculator": c("SSS कैलकुलेटर मासिक वेतन पर कर्मचारी का 5% और नियोक्ता का 10% सरल दर से लगाता है। वास्तविक योगदान Monthly Salary Credit की वेतन श्रेणियों और EC तथा MPF जैसे आधिकारिक मदों पर आधारित है।", "मासिक वेतन PHP में दर्ज करें। यह उपकरण MSC श्रेणी या सदस्यता प्रकार नहीं चुनता और EC, MPF या छूट शामिल नहीं करता।", "इंजन अनुमान: आधार=min(मासिक वेतन, ₱35,000); कर्मचारी=आधार×5%; नियोक्ता=आधार×10%। यह वैधानिक तालिका का सूत्र नहीं है।", "₱20,000 मासिक वेतन पर इंजन कर्मचारी ₱1,000 और नियोक्ता ₱2,000 दिखाता है। 2025 SSS तालिका में नियोक्ता EC अतिरिक्त हो सकता है और MSC श्रेणियाँ लगती हैं; यह पेरोल कटौती नहीं है।", "क्या इसे पेरोल कटौती के रूप में इस्तेमाल करूँ?", "नहीं। 2025 SSS अनुसूची वेतन-श्रेणी MSC, EC और ऊँची श्रेणियों में MPF का उपयोग करती है। वास्तविक राशि के लिए आधिकारिक तालिका और सदस्यता वर्ग जाँचें।"),
  },
  ru: {
    "malaysia-sst-calculator": c("Калькулятор SST Малайзии выполняет арифметический расчёт по введённой пользователем ставке. Он не классифицирует товары и услуги, регистрацию, освобождения или дату операции; сначала проверьте официальную категорию.", "Введите сумму и применимую ставку и укажите, включает ли сумма налог. Выбор ставки остаётся за пользователем.", "Без налога: налог=сумма×ставка÷100; итог=сумма+налог. С налогом: база=итог÷(1+ставка÷100); налог=итог−база.", "Для MYR100 при введённых 8% налог равен MYR8, итог MYR108. 8% — только пример ввода, а не универсальная ставка SST.", "Калькулятор определяет ставку SST для моей операции?", "Нет. С июля 2025 года налог с продаж товаров может составлять 10%, 5%, специальную ставку или не взиматься; налог на услуги зависит от вида услуги и даты. Сверьтесь с официальной классификацией."),
    "philippines-income-tax-calculator": c("Калькулятор подоходного налога Филиппин применяет прогрессивные ставки к годовому налогооблагаемому доходу по таблице BIR, действующей с 1 января 2023 года. Это не полный расчёт декларации.", "Введите годовой налогооблагаемый доход в PHP. Он может отличаться от валовой зарплаты; резидентство, вид дохода, вычеты, зачёты и добровольный режим 8% для имеющих право не учитываются.", "Умножьте каждую часть дохода в предельном диапазоне на её ставку и сложите: 0% до ₱250 000, 15% на следующие ₱150 000, затем 20%, 25%, 30% и 35% сверх ₱8 000 000.", "При доходе ₱1 000 000 таблица BIR даёт налог ₱152 500 и среднюю ставку 15,25%. Личные вычеты и зачёты не применяются.", "Это окончательный налог по моей декларации?", "Нет. Резидентство, категория дохода, вычеты, зачёты и добровольный режим 8% для имеющих право не моделируются. Для подачи декларации используйте применимые инструкции BIR."),
    "philippines-sss-calculator": c("Калькулятор SSS умножает месячную зарплату на упрощённые доли 5% работника и 10% работодателя. Фактические взносы рассчитываются по диапазонам Monthly Salary Credit и официальным компонентам EC и MPF.", "Введите месячную зарплату в PHP. Инструмент не выбирает диапазон MSC или тип членства и не включает EC, MPF и исключения.", "Оценка движка: база=min(месячная зарплата, ₱35 000); работник=база×5%; работодатель=база×10%. Это не расчёт по законной таблице.", "При зарплате ₱20 000 движок показывает ₱1 000 работника и ₱2 000 работодателя. Таблица SSS 2025 может добавить EC работодателя и использует диапазоны MSC; это не удержание из зарплаты.", "Можно использовать это как удержание из зарплаты?", "Нет. График SSS 2025 использует MSC по диапазонам, EC и MPF в верхних диапазонах. Для фактического взноса проверьте официальную таблицу и категорию членства."),
  },
  tr: {
    "malaysia-sst-calculator": c("Malezya SST hesaplayıcısı, kullanıcının girdiği oranla matematiksel hesap yapar. Malları/hizmetleri sınıflandırmaz; kayıt, muafiyet veya işlem tarihini belirlemez. Oranı seçmeden önce resmî kategoriyi doğrulayın.", "Tutar ve uygulanacak oranı girin; tutarın vergi öncesi mi yoksa vergi dâhil mi olduğunu seçin. Doğru oranı kullanıcı belirler.", "Vergi hariç: vergi=tutar×oran÷100; toplam=tutar+vergi. Vergi dâhil: matrah=toplam÷(1+oran÷100); vergi=toplam−matrah.", "MYR100 için girilen %8 oranı MYR8 vergi ve MYR108 toplam verir. %8 yalnızca örnek girdidir, tüm SST işlemlerine uygulanan evrensel oran değildir.", "Hesaplayıcı işlemimin SST oranını buluyor mu?", "Hayır. Temmuz 2025'ten beri satış vergisi mal kategorisine göre %10, %5, özel oran veya muafiyet olabilir; hizmet vergisi de hizmet türüne ve yürürlük tarihine bağlıdır. Resmî sınıflamayı kontrol edin."),
    "philippines-income-tax-calculator": c("Filipinler gelir vergisi hesaplayıcısı yıllık vergilendirilebilir gelire 1 Ocak 2023'ten beri geçerli BIR bireysel artan oranlı tarifesini uygular. Tam bir beyanname hesabı değildir.", "Yıllık vergilendirilebilir geliri PHP cinsinden girin. Brüt ücretle aynı olmayabilir; ikamet, gelir türü, indirimler, krediler ve uygun kişilerin seçebileceği %8 rejimi girdi değildir.", "Her marjinal dilimdeki gelir payını oranla çarpıp toplayın: ₱250.000'e kadar %0, sonraki ₱150.000 için %15, ardından %20, %25, %30 ve ₱8.000.000 üzeri için %35.", "₱1.000.000 vergilendirilebilir gelir BIR tarifesinde ₱152.500 vergi ve %10,25 ortalama oran verir. Kişisel indirim ve krediler uygulanmaz.", "Bu, beyannamemdeki kesin vergi mi?", "Hayır. İkamet, gelir sınıfı, indirimler, krediler ve uygun mükelleflerin seçebileceği %8 seçeneği modellenmez. Beyan için geçerli BIR yönergelerine bakın."),
    "philippines-sss-calculator": c("SSS hesaplayıcısı aylık ücrete çalışan için %5, işveren için %10 basit oran uygular. Gerçek ödemeler Monthly Salary Credit ücret dilimlerine ve EC/MPF gibi resmî tablo kalemlerine dayanır.", "Aylık ücreti PHP cinsinden girin. Araç MSC dilimini veya üyelik kategorisini seçmez; EC, MPF ya da muafiyetleri içermez.", "Motor tahmini: taban=min(aylık ücret, ₱35.000); çalışan=taban×%5; işveren=taban×%10. Bu yasal tablo formülü değildir.", "₱20.000 aylık ücrette motor çalışan ₱1.000 ve işveren ₱2.000 gösterir. 2025 SSS tablosu işveren EC'sini ekleyebilir ve MSC dilimleri kullanır; bu gerçek bordro kesintisi değildir.", "Bunu bordro kesintisi olarak kullanabilir miyim?", "Hayır. 2025 SSS tarifesi dilimlere göre MSC, EC ve üst dilimlerde MPF içerir. Gerçek katkı için resmî tablo ve üyelik türünü kontrol edin."),
  },
  pl: {
    "malaysia-sst-calculator": c("Malezyjski kalkulator SST wykonuje działanie według stawki wprowadzonej przez użytkownika. Nie klasyfikuje towarów ani usług, rejestracji, zwolnień czy daty transakcji; przed wyborem stawki sprawdź oficjalną kategorię.", "Wpisz kwotę i właściwą stawkę oraz wybierz, czy kwota jest przed podatkiem, czy już go zawiera. Użytkownik odpowiada za dobór stawki.", "Bez podatku: podatek=kwota×stawka÷100; suma=kwota+podatek. Z podatkiem: podstawa=suma÷(1+stawka÷100); podatek=suma−podstawa.", "Dla MYR100 i wpisanych 8% podatek wynosi MYR8, a suma MYR108. 8% to tylko przykład, nie uniwersalna stawka SST.", "Czy kalkulator dobiera stawkę SST dla mojej transakcji?", "Nie. Od lipca 2025 podatek od sprzedaży może wynosić 10%, 5%, stawkę szczególną albo być zwolniony zależnie od towaru; podatek od usług zależy także od rodzaju i daty. Sprawdź oficjalną klasyfikację."),
    "philippines-income-tax-calculator": c("Filipiński kalkulator podatku dochodowego stosuje progresywne stawki do rocznego dochodu podlegającego opodatkowaniu według tabeli BIR obowiązującej od 1 stycznia 2023 r. Nie oblicza pełnego zeznania.", "Wpisz roczny dochód do opodatkowania w PHP. Może różnić się od pensji brutto; rezydencja, rodzaj dochodu, odliczenia, ulgi i opcjonalny reżim 8% dla uprawnionych nie są wejściami.", "Pomnóż każdą część dochodu w przedziale krańcowym przez stawkę i zsumuj: 0% do ₱250 000, 15% od kolejnych ₱150 000, potem 20%, 25%, 30% i 35% nad ₱8 000 000.", "Przy ₱1 000 000 dochodu opodatkowanego tabela BIR daje podatek ₱152 500 i średnią stawkę 15,25%. Odliczenia i ulgi osobiste nie są stosowane.", "Czy to ostateczny podatek z mojego zeznania?", "Nie. Rezydencja, kategoria dochodu, odliczenia, ulgi i opcjonalna stawka 8% dla uprawnionych nie są modelowane. Do rozliczenia użyj właściwych wskazówek BIR."),
    "philippines-sss-calculator": c("Kalkulator SSS mnoży miesięczne wynagrodzenie przez uproszczone stawki 5% pracownika i 10% pracodawcy. Rzeczywiste składki korzystają z progów Monthly Salary Credit i oficjalnych pozycji, takich jak EC i MPF.", "Wpisz miesięczne wynagrodzenie w PHP. Narzędzie nie wybiera progu MSC ani rodzaju członkostwa i nie uwzględnia EC, MPF ani zwolnień.", "Szacunek silnika: podstawa=min(wynagrodzenie miesięczne, ₱35 000); pracownik=podstawa×5%; pracodawca=podstawa×10%. To nie ustawowy wzór tabelaryczny.", "Przy ₱20 000 miesięcznie silnik pokazuje ₱1 000 pracownika i ₱2 000 pracodawcy. Tabela SSS 2025 może doliczać pracodawcy EC i stosuje progi MSC; to nie jest potrącenie z listy płac.", "Czy mogę użyć tego jako potrącenia płacowego?", "Nie. Harmonogram SSS 2025 stosuje MSC według progów, EC oraz MPF w wyższych progach. Sprawdź oficjalną tabelę i kategorię członkostwa."),
  },
  fil: {
    "malaysia-sst-calculator": c("Kinakalkula ng Malaysia SST tool na ito ang halaga gamit ang rate na inilagay ng user. Hindi nito inuuri ang produkto o serbisyo, pagpaparehistro, exemption, o petsa ng transaksyon; tingnan muna ang opisyal na kategorya.", "Ilagay ang halaga at naaangkop na rate, at piliin kung bago o kasama na ang buwis. Ikaw ang pipili ng rate.", "Hindi kasama: buwis=halaga×rate÷100; kabuuan=halaga+buwis. Kasama: base=kabuuan÷(1+rate÷100); buwis=kabuuan−base.", "Sa MYR100 at 8% na inilagay, MYR8 ang buwis at MYR108 ang kabuuan. Halimbawa lamang ang 8%, hindi pangkalahatang SST rate.", "Hinahanap ba nito ang SST rate ng transaksyon ko?", "Hindi. Mula Hulyo 2025, maaaring 10%, 5%, partikular na rate, o exempt ang sales tax depende sa produkto; nakadepende rin sa uri at petsa ang service tax. Suriin ang opisyal na classification."),
    "philippines-income-tax-calculator": c("Inilalapat ng calculator na ito ang progresibong BIR individual rates na may bisa mula Enero 1, 2023 sa taunang taxable income. Hindi ito kumpletong tax-return calculator.", "Ilagay ang taunang taxable income sa PHP. Maaaring iba ito sa gross salary; hindi hinihingi ang tax residency, uri ng kita, deductions, credits, o opsyonal na 8% regime para sa kwalipikado.", "I-multiply ang bawat bahagi sa marginal bracket rate nito at pagsamahin: 0% hanggang ₱250,000, 15% sa susunod na ₱150,000, saka 20%, 25%, 30%, at 35% sa lampas ₱8,000,000.", "Sa ₱1,000,000 taxable income, ₱152,500 ang buwis at 15.25% ang average rate ayon sa BIR table. Walang personal deductions o credits na inilalapat.", "Ito ba ang pinal na buwis sa return ko?", "Hindi. Hindi minomodelo ang residency, klase ng kita, deductions, credits, at opsyonal na 8% para sa kwalipikado. Gamitin ang naaangkop na gabay ng BIR sa paghahain."),
    "philippines-sss-calculator": c("Minumultiply ng SSS calculator ang buwanang sahod sa payak na 5% employee at 10% employer rates. Ang aktuwal na hulog ay gumagamit ng Monthly Salary Credit brackets at mga opisyal na bahagi gaya ng EC at MPF.", "Ilagay ang buwanang sahod sa PHP. Hindi pumipili ang tool ng MSC bracket o membership type at hindi nito isinasama ang EC, MPF, o exemption.", "Tantiya ng engine: base=min(buwanang sahod, ₱35,000); empleyado=base×5%; employer=base×10%. Hindi ito ang legal na table formula.", "Sa ₱20,000 buwanang sahod, ₱1,000 employee at ₱2,000 employer ang ipinapakita. Maaaring idagdag ng SSS 2025 table ang employer EC at gumagamit ito ng MSC brackets; hindi ito payroll deduction.", "Maaari ko ba itong gamitin sa payroll?", "Hindi. Gumagamit ang 2025 SSS schedule ng MSC ayon sa bracket, EC, at MPF sa matataas na bracket. Tingnan ang opisyal na talahanayan at membership category."),
  },
  bn: {
    "malaysia-sst-calculator": c("মালয়েশিয়ার SST ক্যালকুলেটর ব্যবহারকারীর দেওয়া হার দিয়ে অঙ্ক করে। এটি পণ্য/সেবা, নিবন্ধন, অব্যাহতি বা লেনদেনের তারিখ নির্ধারণ করে না; হার বাছার আগে সরকারি শ্রেণি যাচাই করুন।", "অঙ্ক ও প্রযোজ্য হার লিখে নির্বাচন করুন অঙ্কটি করের আগে নাকি করসহ। সঠিক হার বাছা ব্যবহারকারীর দায়িত্ব।", "কর বাদে: কর=অঙ্ক×হার÷100; মোট=অঙ্ক+কর। করসহ: কর-পূর্ব ভিত্তি=মোট÷(1+হার÷100); কর=মোট−ভিত্তি।", "MYR100-এ 8% দিলে কর MYR8 এবং মোট MYR108। 8% কেবল উদাহরণ, সর্বজনীন SST হার নয়।", "এটি কি আমার লেনদেনের SST হার বের করে?", "না। জুলাই 2025 থেকে পণ্যভেদে বিক্রয় কর 10%, 5%, নির্দিষ্ট হার বা অব্যাহতি হতে পারে; সেবা করও ধরন ও কার্যকর তারিখের ওপর নির্ভর করে। সরকারি শ্রেণি যাচাই করুন।"),
    "philippines-income-tax-calculator": c("ফিলিপাইনের এই আয়কর ক্যালকুলেটর 1 জানুয়ারি 2023 থেকে কার্যকর BIR ব্যক্তিগত প্রগতিশীল হার বার্ষিক করযোগ্য আয়ে প্রয়োগ করে। এটি পূর্ণ কর-রিটার্ন হিসাব নয়।", "বার্ষিক করযোগ্য আয় PHP-তে লিখুন। এটি মোট বেতনের সমান নাও হতে পারে; কর-নিবাস, আয়ের ধরন, কর্তন, ক্রেডিট এবং যোগ্যদের ঐচ্ছিক 8% পদ্ধতি ইনপুট নয়।", "প্রতিটি প্রান্তিক কর-স্তরের আয়াংশে হার প্রয়োগ করে যোগ করুন: ₱250,000 পর্যন্ত 0%, পরের ₱150,000-এ 15%, এরপর 20%, 25%, 30%, এবং ₱8,000,000-এর অতিরিক্তে 35%。", "₱1,000,000 করযোগ্য আয়ে BIR সারণি অনুযায়ী কর ₱152,500 এবং গড় হার 15.25%। ব্যক্তিগত কর্তন বা ক্রেডিট এতে নেই।", "এটি কি আমার রিটার্নের চূড়ান্ত কর?", "না। নিবাস, আয়ের শ্রেণি, কর্তন, ক্রেডিট এবং যোগ্য করদাতার ঐচ্ছিক 8% পদ্ধতি মডেল করা হয় না। রিটার্নের জন্য প্রযোজ্য BIR নির্দেশনা দেখুন।"),
    "philippines-sss-calculator": c("SSS ক্যালকুলেটর মাসিক বেতনে কর্মীর 5% ও নিয়োগকর্তার 10% সরল হার গুণ করে। প্রকৃত অবদান Monthly Salary Credit-এর স্তর এবং EC, MPF-এর মতো সরকারি সারণির অংশের ওপর নির্ভর করে।", "মাসিক বেতন PHP-তে লিখুন। এটি MSC স্তর বা সদস্যপদ বেছে নেয় না এবং EC, MPF বা অব্যাহতি যোগ করে না।", "ইঞ্জিনের অনুমান: ভিত্তি=min(মাসিক বেতন, ₱35,000); কর্মী=ভিত্তি×5%; নিয়োগকর্তা=ভিত্তি×10%。 এটি আইনগত সারণির সূত্র নয়।", "₱20,000 মাসিক বেতনে ইঞ্জিন কর্মীর ₱1,000 ও নিয়োগকর্তার ₱2,000 দেখায়। 2025 SSS সারণিতে নিয়োগকর্তার EC যোগ হতে পারে এবং MSC স্তর ব্যবহৃত হয়; এটি payroll কর্তন নয়।", "এই অঙ্ক payroll থেকে কাটতে পারি?", "না। 2025 SSS সময়সূচি বেতন-স্তরের MSC, EC এবং উচ্চ স্তরে MPF ব্যবহার করে। প্রকৃত অবদানের জন্য সরকারি সারণি ও সদস্যের ধরন দেখুন।"),
  },
  uk: {
    "malaysia-sst-calculator": c("Малайзійський калькулятор SST виконує арифметичний розрахунок за ставкою, введеною користувачем. Він не класифікує товари/послуги, реєстрацію, пільги чи дату операції; спершу перевірте офіційну категорію.", "Введіть суму й застосовну ставку та виберіть, чи сума до оподаткування, чи вже містить податок. Ставку обирає користувач.", "Без податку: податок=сума×ставка÷100; разом=сума+податок. З податком: база=разом÷(1+ставка÷100); податок=разом−база.", "Для MYR100 за введеної ставки 8% податок становить MYR8, разом MYR108. 8% — лише приклад, а не універсальна ставка SST.", "Чи визначає калькулятор ставку SST для моєї операції?", "Ні. Із липня 2025 року продаж товарів може оподатковуватися за ставкою 10%, 5%, спеціальною ставкою або бути звільненим; послуги залежать від виду й дати. Перевірте офіційну класифікацію."),
    "philippines-income-tax-calculator": c("Філіппінський калькулятор застосовує прогресивні ставки до річного оподатковуваного доходу за таблицею BIR для фізичних осіб, чинною з 1 січня 2023 року. Це не повний розрахунок декларації.", "Введіть річний оподатковуваний дохід у PHP. Він може відрізнятися від валової зарплати; резидентство, вид доходу, відрахування, кредити й опційний режим 8% для тих, хто має право, не вводяться.", "Помножте кожну частину граничного діапазону на ставку й підсумуйте: 0% до ₱250 000, 15% на наступні ₱150 000, потім 20%, 25%, 30% і 35% понад ₱8 000 000.", "За доходу ₱1 000 000 таблиця BIR дає податок ₱152 500 і середню ставку 15,25%. Особисті відрахування й кредити не застосовуються.", "Це остаточний податок у моїй декларації?", "Ні. Резидентство, категорія доходу, відрахування, кредити й опційний режим 8% для відповідних платників не моделюються. Для подання декларації користуйтеся застосовними інструкціями BIR."),
    "philippines-sss-calculator": c("Калькулятор SSS множить місячну зарплату на прості частки 5% працівника та 10% роботодавця. Фактичні внески спираються на діапазони Monthly Salary Credit та офіційні складові EC і MPF.", "Введіть місячну зарплату в PHP. Інструмент не обирає діапазон MSC або тип членства й не враховує EC, MPF чи винятки.", "Оцінка двигуна: база=min(місячна зарплата, ₱35 000); працівник=база×5%; роботодавець=база×10%. Це не законний табличний розрахунок.", "За ₱20 000 на місяць двигун показує ₱1 000 працівника й ₱2 000 роботодавця. Таблиця SSS 2025 може додавати EC роботодавця та використовує діапазони MSC; це не сума для утримання із зарплати.", "Чи можна використати це як зарплатне утримання?", "Ні. Таблиця SSS 2025 застосовує MSC за діапазонами, EC і MPF у вищих діапазонах. Перевірте офіційну таблицю й категорію членства."),
  },
  ms: {
    "malaysia-sst-calculator": c("Kalkulator SST Malaysia membuat kiraan menggunakan kadar yang dimasukkan pengguna. Ia tidak mengelaskan barang/perkhidmatan, pendaftaran, pengecualian atau tarikh transaksi; semak kategori rasmi sebelum memilih kadar.", "Masukkan amaun dan kadar berkenaan, kemudian pilih sama ada amaun sebelum cukai atau termasuk cukai. Pengguna bertanggungjawab memilih kadar.", "Tidak termasuk cukai: cukai=amaun×kadar÷100; jumlah=amaun+cukai. Termasuk cukai: asas=jumlah÷(1+kadar÷100); cukai=jumlah−asas.", "MYR100 pada kadar input 8% menghasilkan cukai MYR8 dan jumlah MYR108. 8% hanya contoh pengiraan, bukan kadar SST sejagat.", "Adakah kalkulator mencari kadar SST transaksi saya?", "Tidak. Sejak Julai 2025, cukai jualan barang boleh 10%, 5%, kadar khusus atau dikecualikan; cukai perkhidmatan juga bergantung pada jenis dan tarikh kuat kuasa. Semak klasifikasi rasmi."),
    "philippines-income-tax-calculator": c("Kalkulator cukai pendapatan Filipina menggunakan kadar progresif pada pendapatan bercukai tahunan menurut jadual individu BIR berkuat kuasa 1 Januari 2023. Ia bukan pengiraan penyata cukai lengkap.", "Masukkan pendapatan bercukai tahunan dalam PHP. Nilai ini mungkin berbeza daripada gaji kasar; pemastautin cukai, jenis pendapatan, potongan, kredit dan rejim pilihan 8% bagi yang layak tidak diminta.", "Darab setiap bahagian pendapatan pada jalur marginal dengan kadarnya dan jumlahkan: 0% hingga ₱250,000, 15% pada ₱150,000 seterusnya, kemudian 20%, 25%, 30% dan 35% melebihi ₱8,000,000.", "Pendapatan bercukai ₱1,000,000 menghasilkan cukai ₱152,500 dan kadar purata 15.25% menurut jadual progresif BIR. Potongan atau kredit peribadi tidak digunakan.", "Adakah ini cukai akhir dalam penyata saya?", "Tidak. Pemastautin, kategori pendapatan, potongan, kredit dan pilihan 8% bagi pembayar cukai yang layak tidak dimodelkan. Rujuk panduan BIR yang berkenaan untuk pemfailan."),
    "philippines-sss-calculator": c("Kalkulator SSS mendarab gaji bulanan dengan kadar mudah 5% pekerja dan 10% majikan. Caruman sebenar menggunakan jalur Monthly Salary Credit dan item jadual rasmi seperti EC dan MPF.", "Masukkan gaji bulanan dalam PHP. Alat ini tidak memilih jalur MSC atau jenis keahlian dan tidak memasukkan EC, MPF atau pengecualian.", "Anggaran enjin: asas=min(gaji bulanan, ₱35,000); pekerja=asas×5%; majikan=asas×10%. Ini bukan formula jadual statutori.", "Pada gaji ₱20,000, enjin menunjukkan ₱1,000 pekerja dan ₱2,000 majikan. Jadual SSS 2025 mungkin menambah EC majikan dan menggunakan jalur MSC; ini bukan potongan gaji sebenar.", "Bolehkah jumlah ini digunakan untuk potongan gaji?", "Tidak. Jadual SSS 2025 menggunakan MSC mengikut jalur, EC dan MPF pada jalur tinggi. Semak jadual rasmi dan kategori keahlian."),
  },
  sv: {
    "malaysia-sst-calculator": c("Den malaysiska SST-kalkylatorn räknar med en skattesats som användaren anger. Den klassificerar inte varor eller tjänster och avgör inte registrering, undantag eller transaktionsdatum; kontrollera den officiella kategorin först.", "Ange belopp och tillämplig skattesats och välj om beloppet är före skatt eller redan inklusive skatt. Användaren ansvarar för satsen.", "Exklusive skatt: skatt=belopp×sats÷100; total=belopp+skatt. Inklusive skatt: underlag=total÷(1+sats÷100); skatt=total−underlag.", "MYR100 med angivna 8% ger MYR8 i skatt och MYR108 totalt. 8% är bara ett räkneexempel, inte en allmän SST-sats.", "Hittar kalkylatorn SST-satsen för min transaktion?", "Nej. Från juli 2025 kan försäljningsskatt på varor vara 10%, 5%, en särskild sats eller undantagen; tjänsteskatt beror också på tjänst och datum. Kontrollera officiell klassificering."),
    "philippines-income-tax-calculator": c("Den filippinska inkomstskattekalkylatorn tillämpar progressiva satser på årlig beskattningsbar inkomst enligt BIR:s individuella tabell från 1 januari 2023. Den beräknar inte en fullständig deklaration.", "Ange årlig beskattningsbar inkomst i PHP. Den kan skilja sig från bruttolönen; skatterättslig hemvist, inkomsttyp, avdrag, krediter och valbar 8-procentsregel saknas.", "Multiplicera varje inkomstbit i marginalskiktet med dess sats och summera: 0% till ₱250 000, 15% på nästa ₱150 000, därefter 20%, 25%, 30% och 35% över ₱8 000 000.", "Vid ₱1 000 000 beskattningsbar inkomst ger BIR-tabellen ₱152 500 skatt och 15,25% genomsnittlig sats. Personliga avdrag och krediter räknas inte av.", "Är detta min slutliga skatt i deklarationen?", "Nej. Hemvist, inkomstkategori, avdrag, krediter och valbar 8-procentsregel för berättigade modelleras inte. Följ relevanta BIR-instruktioner vid deklaration."),
    "philippines-sss-calculator": c("SSS-kalkylatorn multiplicerar månadslönen med enkla andelar på 5% för arbetstagaren och 10% för arbetsgivaren. Faktiska avgifter följer Monthly Salary Credit-intervall och officiella poster som EC och MPF.", "Ange månadslön i PHP. Verktyget väljer inte MSC-intervall eller medlemstyp och inkluderar inte EC, MPF eller undantag.", "Motorns uppskattning: bas=min(månadslön, ₱35 000); arbetstagare=bas×5%; arbetsgivare=bas×10%. Detta är inte den lagstadgade tabellformeln.", "Vid ₱20 000 månadslön visar motorn ₱1 000 arbetstagare och ₱2 000 arbetsgivare. SSS-tabellen 2025 kan lägga till arbetsgivarens EC och använder MSC-intervall; det är inget korrekt löneavdrag.", "Kan jag använda beloppet som löneavdrag?", "Nej. SSS-schemat 2025 använder MSC efter löneintervall, EC och MPF i de högre intervallen. Kontrollera den officiella tabellen och medlemskategorin."),
  },
  cs: {
    "malaysia-sst-calculator": c("Malajsijská kalkulačka SST počítá podle sazby zadané uživatelem. Neurčuje klasifikaci zboží ani služeb, registraci, osvobození či datum transakce; před volbou sazby ověřte oficiální kategorii.", "Zadejte částku a použitelnou sazbu a zvolte, zda částka nezahrnuje daň, nebo ji již obsahuje. Za výběr sazby odpovídá uživatel.", "Bez daně: daň=částka×sazba÷100; celkem=částka+daň. Včetně daně: základ=celkem÷(1+sazba÷100); daň=celkem−základ.", "Při MYR100 a zadaných 8% je daň MYR8 a celkem MYR108. Osm procent je pouze vstup příkladu, nikoli univerzální sazba SST.", "Určí kalkulačka sazbu SST pro mou transakci?", "Ne. Od července 2025 může být pro zboží sazba 10%, 5%, zvláštní sazba nebo osvobození; služba závisí na druhu a datu účinnosti. Ověřte oficiální klasifikaci."),
    "philippines-income-tax-calculator": c("Filipínská kalkulačka daně z příjmů uplatňuje progresivní sazby na roční zdanitelný příjem podle individuální tabulky BIR platné od 1. ledna 2023. Nejde o kompletní výpočet přiznání.", "Zadejte roční zdanitelný příjem v PHP. Nemusí se rovnat hrubé mzdě; rezidence, druh příjmů, odpočty, kredity a volitelný 8% režim pro oprávněné osoby nejsou vstupy.", "Vynásobte části příjmu v mezních pásmech jejich sazbou a sečtěte: 0% do ₱250 000, 15% z dalších ₱150 000, poté 20%, 25%, 30% a 35% nad ₱8 000 000.", "Při zdanitelném příjmu ₱1 000 000 dává tabulka BIR daň ₱152 500 a průměrnou sazbu 15,25%. Osobní odpočty ani kredity se neuplatňují.", "Je to konečná daň z mého přiznání?", "Ne. Rezidence, kategorie příjmu, odpočty, kredity ani volitelný 8% režim oprávněných osob nejsou modelovány. Pro podání použijte příslušné pokyny BIR."),
    "philippines-sss-calculator": c("Kalkulačka SSS násobí měsíční mzdu jednoduchými sazbami 5% zaměstnance a 10% zaměstnavatele. Skutečné příspěvky vycházejí z pásem Monthly Salary Credit a oficiálních položek EC a MPF.", "Zadejte měsíční mzdu v PHP. Nástroj nevybírá pásmo MSC ani typ členství a nezahrnuje EC, MPF nebo výjimky.", "Odhad motoru: základ=min(měsíční mzda, ₱35 000); zaměstnanec=základ×5%; zaměstnavatel=základ×10%. Nejde o zákonný tabulkový výpočet.", "Při ₱20 000 měsíčně motor ukáže ₱1 000 zaměstnanec a ₱2 000 zaměstnavatel. Tabulka SSS 2025 může přidat EC zaměstnavatele a používá pásma MSC; nejde o správnou srážku ze mzdy.", "Mohu výsledek použít jako srážku ze mzdy?", "Ne. Sazebník SSS 2025 používá MSC podle pásem, EC a ve vyšších pásmech MPF. Ověřte oficiální tabulku a kategorii členství."),
  },
  ro: {
    "malaysia-sst-calculator": c("Calculatorul SST din Malaysia face calculul folosind cota introdusă de utilizator. Nu clasifică bunuri sau servicii și nu stabilește înregistrarea, scutirile ori data tranzacției; verificați categoria oficială înainte de a alege cota.", "Introduceți suma și cota aplicabilă și selectați dacă suma este fără taxă sau include deja taxa. Utilizatorul alege cota.", "Fără taxă: taxă=sumă×cotă÷100; total=sumă+taxă. Cu taxă inclusă: bază=total÷(1+cotă÷100); taxă=total−bază.", "La MYR100 și o cotă introdusă de 8%, taxa este MYR8 și totalul MYR108. 8% este doar un exemplu de calcul, nu o cotă SST universală.", "Calculatorul identifică rata SST pentru tranzacția mea?", "Nu. Din iulie 2025, taxa pe vânzări poate fi 10%, 5%, o cotă specifică sau scutită în funcție de bun; taxa pe servicii depinde și de tip și dată. Verificați clasificarea oficială."),
    "philippines-income-tax-calculator": c("Calculatorul filipinez aplică cote progresive venitului anual impozabil conform tabelului individual BIR în vigoare de la 1 ianuarie 2023. Nu calculează o declarație fiscală completă.", "Introduceți venitul anual impozabil în PHP. Poate fi diferit de salariul brut; rezidența, tipul venitului, deducerile, creditele și regimul opțional de 8% pentru cei eligibili nu sunt intrări.", "Înmulțiți fiecare parte din tranșa marginală cu rata sa și însumați: 0% până la ₱250.000, 15% pentru următorii ₱150.000, apoi 20%, 25%, 30% și 35% peste ₱8.000.000.", "La venit impozabil de ₱1.000.000, tabelul BIR produce impozit ₱152.500 și o rată medie de 15,25%. Deducerile și creditele personale nu sunt aplicate.", "Este acesta impozitul final din declarația mea?", "Nu. Rezidența, categoria venitului, deducerile, creditele și regimul opțional de 8% pentru persoanele eligibile nu sunt modelate. Consultați instrucțiunile BIR aplicabile."),
    "philippines-sss-calculator": c("Calculatorul SSS înmulțește salariul lunar cu cote simple de 5% pentru angajat și 10% pentru angajator. Contribuțiile reale folosesc tranșe Monthly Salary Credit și poziții oficiale precum EC și MPF.", "Introduceți salariul lunar în PHP. Instrumentul nu alege tranșa MSC sau tipul de membru și nu include EC, MPF ori scutiri.", "Estimarea motorului: bază=min(salariu lunar, ₱35.000); angajat=bază×5%; angajator=bază×10%. Nu este formula tabelului legal.", "La ₱20.000 lunar, motorul arată ₱1.000 angajat și ₱2.000 angajator. Tabelul SSS 2025 poate adăuga EC al angajatorului și folosește tranșe MSC; nu este o reținere corectă din salariu.", "Pot folosi rezultatul pentru reținerea salarială?", "Nu. Programul SSS 2025 folosește MSC pe tranșe, EC și MPF la tranșele superioare. Verificați tabelul oficial și categoria de membru."),
  },
  el: {
    "malaysia-sst-calculator": c("Ο μαλαισιανός υπολογιστής SST κάνει αριθμητικό υπολογισμό με τον συντελεστή που εισάγει ο χρήστης. Δεν ταξινομεί αγαθά ή υπηρεσίες ούτε καθορίζει εγγραφή, απαλλαγή ή ημερομηνία συναλλαγής· ελέγξτε πρώτα την επίσημη κατηγορία.", "Εισαγάγετε ποσό και εφαρμοστέο συντελεστή και επιλέξτε αν το ποσό είναι προ φόρου ή τον περιλαμβάνει. Ο χρήστης επιλέγει τον συντελεστή.", "Χωρίς φόρο: φόρος=ποσό×συντελεστής÷100· σύνολο=ποσό+φόρος. Με φόρο: βάση=σύνολο÷(1+συντελεστής÷100)· φόρος=σύνολο−βάση.", "Για MYR100 και εισαγόμενο 8%, ο φόρος είναι MYR8 και το σύνολο MYR108. Το 8% είναι μόνο παράδειγμα υπολογισμού, όχι καθολικός συντελεστής SST.", "Βρίσκει ο υπολογιστής τον συντελεστή SST της συναλλαγής μου;", "Όχι. Από τον Ιούλιο 2025, ο φόρος πώλησης αγαθών μπορεί να είναι 10%, 5%, ειδικός συντελεστής ή να υπάρχει απαλλαγή· ο φόρος υπηρεσιών εξαρτάται επίσης από το είδος και την ημερομηνία. Ελέγξτε την επίσημη ταξινόμηση."),
    "philippines-income-tax-calculator": c("Ο φιλιππινέζικος υπολογιστής εφαρμόζει προοδευτικούς συντελεστές στο ετήσιο φορολογητέο εισόδημα με βάση τον ατομικό πίνακα BIR από 1 Ιανουαρίου 2023. Δεν υπολογίζει πλήρη φορολογική δήλωση.", "Εισαγάγετε ετήσιο φορολογητέο εισόδημα σε PHP. Μπορεί να διαφέρει από τον μικτό μισθό· κατοικία, είδος εισοδήματος, εκπτώσεις, πιστώσεις και προαιρετικό καθεστώς 8% για δικαιούχους δεν είναι είσοδοι.", "Πολλαπλασιάστε κάθε μέρος του οριακού κλιμακίου με τον συντελεστή του και αθροίστε: 0% έως ₱250.000, 15% στα επόμενα ₱150.000, μετά 20%, 25%, 30% και 35% πάνω από ₱8.000.000.", "Για φορολογητέο εισόδημα ₱1.000.000, ο πίνακας BIR δίνει φόρο ₱152.500 και μέσο συντελεστή 15,25%. Δεν υπολογίζονται προσωπικές εκπτώσεις ή πιστώσεις.", "Είναι αυτός ο τελικός φόρος της δήλωσής μου;", "Όχι. Κατοικία, κατηγορία εισοδήματος, εκπτώσεις, πιστώσεις και προαιρετικό 8% για δικαιούχους δεν μοντελοποιούνται. Για τη δήλωση συμβουλευτείτε τις κατάλληλες οδηγίες BIR."),
    "philippines-sss-calculator": c("Ο υπολογιστής SSS πολλαπλασιάζει τον μηνιαίο μισθό με απλά ποσοστά 5% εργαζομένου και 10% εργοδότη. Οι πραγματικές εισφορές ακολουθούν κλίμακες Monthly Salary Credit και επίσημα στοιχεία όπως EC και MPF.", "Εισαγάγετε μηνιαίο μισθό σε PHP. Το εργαλείο δεν επιλέγει κλίμακα MSC ή τύπο μέλους και δεν περιλαμβάνει EC, MPF ή εξαιρέσεις.", "Εκτίμηση μηχανισμού: βάση=min(μηνιαίος μισθός, ₱35.000); εργαζόμενος=βάση×5%; εργοδότης=βάση×10%. Δεν είναι ο νόμιμος υπολογισμός πίνακα.", "Με ₱20.000 τον μήνα, ο μηχανισμός δείχνει ₱1.000 εργαζομένου και ₱2.000 εργοδότη. Ο πίνακας SSS 2025 μπορεί να προσθέτει εργοδοτικό EC και χρησιμοποιεί κλίμακες MSC· δεν πρόκειται για σωστή παρακράτηση.", "Μπορώ να χρησιμοποιήσω το αποτέλεσμα ως παρακράτηση μισθού;", "Όχι. Το πρόγραμμα SSS 2025 χρησιμοποιεί MSC ανά κλίμακα, EC και MPF στις υψηλές κλίμακες. Ελέγξτε τον επίσημο πίνακα και την κατηγορία μέλους."),
  },
};
